    assert_eq!(r.get("hello"), Some(&3), "hello count wrong");

    let r2 = word_count("one two, two THREE!");
    assert_eq!(r2.get("one"), Some(&1));
    assert_eq!(r2.get("two"), Some(&2));
    assert_eq!(r2.get("three"), Some(&1));

    let r3 = word_count("  spaces   everywhere  ");
    assert_eq!(r3.get("spaces"), Some(&1));
    assert_eq!(r3.get("everywhere"), Some(&1));

    let r4 = word_count("");
    assert!(r4.is_empty(), "empty string should yield empty map");

    println!("ALL TESTS PASSED");
}
