#!/bin/bash
set -e

cp binary_search.rs /tmp/bs_lib.rs

cat > /tmp/bs_test_main.rs << 'EOF'
mod bs_lib {
    include!("/tmp/bs_lib.rs");
}
use bs_lib::binary_search;

fn main() {
    let v = vec![1, 3, 5, 7, 9, 11];

    // Found cases
    assert_eq!(binary_search(&v, &1), Ok(0), "first element");
    assert_eq!(binary_search(&v, &11), Ok(5), "last element");
    let mid = binary_search(&v, &5).unwrap();
    assert_eq!(v[mid], 5, "middle element");

    // Not found cases
    assert_eq!(binary_search(&v, &0), Err(0), "before first");
    assert_eq!(binary_search(&v, &2), Err(1), "between 1 and 3");
    assert_eq!(binary_search(&v, &12), Err(6), "after last");

    // Empty slice
    let empty: Vec<i32> = vec![];
    assert_eq!(binary_search(&empty, &5), Err(0), "empty slice");

    // Single element
    assert_eq!(binary_search(&[42], &42), Ok(0));
    assert_eq!(binary_search(&[42], &10), Err(0));
    assert_eq!(binary_search(&[42], &99), Err(1));

    println!("ALL TESTS PASSED");
}
EOF

