import { TypedEmitter } from './event_emitter';

type MyEvents = { click: { x: number; y: number }; close: void };
const emitter = new TypedEmitter<MyEvents>();

// on + emit
const calls: number[] = [];
const handler = (d: { x: number; y: number }) => calls.push(d.x);
emitter.on('click', handler);
const had = emitter.emit('click', { x: 10, y: 20 });
console.assert(had === true, 'emit with listener should return true');
console.assert(calls[0] === 10, 'listener should have been called');

// emit with no listeners
const had2 = emitter.emit('close', undefined as void);
console.assert(had2 === false, 'emit with no listeners should return false');

// off
emitter.off('click', handler);
console.assert(emitter.listenerCount('click') === 0, 'after off, count should be 0');
emitter.emit('click', { x: 99, y: 0 });
console.assert(calls.length === 1, 'removed listener should not be called again');

// once
const onceCalls: number[] = [];
emitter.once('click', (d) => onceCalls.push(d.x));
console.assert(emitter.listenerCount('click') === 1, 'once registers listener');
emitter.emit('click', { x: 1, y: 0 });
emitter.emit('click', { x: 2, y: 0 });
console.assert(onceCalls.length === 1, 'once listener fires only once');
console.assert(onceCalls[0] === 1, 'once listener gets correct data');
console.assert(emitter.listenerCount('click') === 0, 'once removed after fire');

// multiple listeners
emitter.on('click', () => {});
emitter.on('click', () => {});
console.assert(emitter.listenerCount('click') === 2, 'two listeners registered');

console.log('ALL TESTS PASSED');
